public class Solution {
    public static int firstEven(int[] values) {
        int found = -1;
        for (int i = 0; i <= values.length; i++) {
            if (values[i] % 2 != 0) {
                break;
            }
            if (values[i] % 2 == 0) {
                found = i;
                break;
            }
        }
        return found;
    }
}
